import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from "axios";

export default function Dashboard() {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [user, setUser] = useState({});
    const [stats, setStats] = useState({});

    useEffect(() => {
        const token = localStorage.getItem("token");
        if (!token) return navigate("/login");

        axios.get("http://127.0.0.1:5000/api/dashboard", {
            headers: { Authorization: `Bearer ${token}` }
        })
            .then(res => {
                setUser(res.data.user);
                setStats(res.data.stats);
            })
            .catch(err => {
                if (err.response?.status === 401 || err.response?.status === 403) {
                    localStorage.removeItem("token");
                    return navigate("/login");
                }
                setError(err.response?.data?.message || err.message);
            })
            .finally(() => setLoading(false));
    }, [navigate]);

    if (loading) return <Center>Loading dashboard…</Center>;
    if (error) return <Alert>{error}</Alert>;

    const isAdmin = user?.primary_role?.toLowerCase() === "admin";

    return (
        <div className="container mt-4 pt-3">

            {/* Logout Button */}
            <div className="text-end">
                <ul className="navbar-nav me-auto mb-2 mb-lg-0">
                    <li className="nav-item">
                        <Link className="nav-link" to="/">Dashboard</Link>
                    </li>
                    <li className="nav-item">
                        <Link className="nav-link" to="/about">Profile</Link>
                    </li>
                    <li className="nav-item">
                        <Link className="nav-link active" to="/contacts">Contacts</Link>
                    </li>
                </ul>
                <button
                    className="btn btn-outline-danger btn-sm"
                    onClick={() => {
                        localStorage.removeItem("token");
                        navigate("/login");
                    }}
                >
                    Logout
                </button>
            </div>

            {/* User Info */}
            <div className="text-center">
                <h2>Welcome, {user.fullname}</h2>
                <p className="text-muted">{user.email}</p>
                <hr />
            </div>

            {/* Admin or User Dashboard Section */}
            {isAdmin ? <AdminSection stats={stats} /> : <UserSection role={user.primary_role} />}
        </div>
    );
}

const Center = ({ children }) => <div className="container mt-5 text-center">{children}</div>;
const Alert = ({ children }) => <div className="container mt-5"><div className="alert alert-danger text-center">{children}</div></div>;

function AdminSection({ stats }) {
    const items = [
        ["👥 Users", stats.total_users, "/showallusers", "primary"],
        ["📝 Consents", stats.total_consents, "/showallconsents", "success"],
        ["💬 Feedbacks", stats.total_feedbacks, "/showallfeedbacks", "warning"],
        ["⚖️ Grievances", stats.total_grievances, "/admin/grievances", "danger"]
    ];

    return (
        <>
            <div className="text-center mt-4">
                <h3 className="text-primary">Admin Dashboard</h3>
                <p>Manage users, companies, and consent data.</p>
            </div>

            <div className="row text-center mt-4">
                {items.map(([title, value, link, color], i) => (
                    <div className="col-md-3 mb-3" key={i}>
                        <div className={`card bg-${color} text-white`}>
                            <div className="card-body text-center">
                                <h5>{title}</h5>
                                <h2>{value || 0}</h2>
                                <a href={link} className="btn btn-light btn-sm mt-2">Open</a>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </>
    );
}

function UserSection({ role }) {
    const roleName = role?.charAt(0).toUpperCase() + role?.slice(1);

    const actions = [
        ["Manage Consent", "/consent/status", "primary"],
        ["My Consents", "/myconsents", "success"],
        ["My Grievances", "/mygrievances", "warning"],
        ["My Notifications", "/notifications", "info"]
    ];

    return (
        <div className="text-center mt-4">
            <h3 className="text-success">{roleName} Dashboard</h3>
            <p>Welcome to your personalized DPCMS dashboard.</p>

            <div className="d-flex flex-wrap justify-content-center gap-3 mt-4">
                {actions.map(([text, link, color], i) => (
                    <a key={i} href={link} className={`btn btn-${color}`}>{text}</a>
                ))}
            </div>
        </div>
    );
}
